    for a in univ:
        try:
            m = obs.hist(a, 'mid', L+20)
        except:
            continue
        if m is None:
            continue
        try:
            n = len(m)
            if n < L+1:
                continue
            cur = float(m[-1])
            past = float(m[-L-1])
        except:
            continue
        if not (cur == cur and past == past):
            continue
        r = cur - past
        if r != r:
            continue
        try:
            w = m[-L-1:]
            dd = np.diff(w)
            v = float(np.nanstd(dd))
        except:
            v = float('nan')
        if not (v == v) or v <= 0:
            continue
        thresh = 2.0 * v
        if r > thresh:
            outs[a] = 1.0
        elif r < -thresh:
            outs[a] = -1.0
    return outs

